return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'Next.js revalidate','pot-creation-date'=>'2026-08-20T13:45:46+00:00','po-revision-date'=>'2026-09-24 12:00+0200','x-generator'=>'Poedit 3.9','messages'=>['Next.js Revalidate'=>'Next.js Revalidate','https://github.com/superhuit-agency/nextjs-revalidate.git'=>'https://github.com/superhuit-agency/nextjs-revalidate.git','Tells a Next.js front-end which WordPress content changed — posts, menus, templates, redirects — so it can revalidate whatever it cached from it, on save and from the admin.'=>'Indique à un front-end Next.js quels contenus WordPress ont changé — articles, menus, modèles, redirections — afin qu’il puisse revalider tout ce qu’il en a mis en cache, à l’enregistrement et depuis l’administration.','superhuit'=>'superhuit','https://www.superhuit.ch'=>'https://www.superhuit.ch','Next.js revalidate is not keeping this site up to date — %1$d of the last %2$d revalidations failed. Content is still saved, but the front-end is serving pages which are quietly out of date.'=>'Next.js revalidate ne parvient pas à maintenir ce site à jour : %1$d des %2$d dernières revalidations ont échoué. Le contenu est toujours enregistré, mais le front-end affiche des pages qui sont, sans que l\'on s\'en rende compte, obsolètes.','Most recent error: %s.'=>'Dernière erreur : %s.','Other errors occurred as well.'=>'D\'autres erreurs se sont également produites.','Please contact a site administrator.'=>'Veuillez contacter un administrateur du site.','Check the Next.js revalidate settings'=>'Vérifier les paramètres Next.js Revalidate','the front-end could not be reached'=>'impossible d\'accéder au Frontend','the front-end rejected the secret'=>'le front-end a rejeté le secret','the front-end answered %s'=>'le front-end a répondu %s','The front-end answered without a status code.'=>'Le front-end a répondu sans code d\'état.','The front-end answered %d.'=>'The front-end answered %d.','Revalidate post “%s”'=>'Revalider l’article « %s »','Revalidate'=>'Revalider','Sorry, you are not allowed to revalidate this post.'=>'Désolé, vous n’êtes pas autorisé(e) à revalider cet article.','Admin top bar menuRevalidate this page'=>'Revalider cette page','Admin top bar menuTell the front-end to revalidate the page currently being edited.'=>'Demander au front-end de revalider la page en cours d’édition.','“%s”: the revalidation was sent to the front-end.'=>'« %s » : la revalidation a été envoyée au front-end.','Unable to revalidate. Please try again or contact an administrator.'=>'Impossible de revalider. Veuillez réessayer ou contacter un administrateur.','%d post: the revalidation was sent to the front-end.'=>'%d article : la revalidation a été envoyée au front-end.' . "\0" . '%d articles : la revalidation a été envoyée au front-end.','Admin top bar menuAll'=>'Tout','Admin top bar menuTell the front-end to revalidate everything it cached from these posts.'=>'Demander au front-end de revalider tout ce qu’il a mis en cache à partir de ces articles.','Revalidate all: nothing was sent, this site is not configured.'=>'Tout revalider : rien n’a été envoyé, ce site n’est pas configuré.','Purge all: %d pages added to purge. Please wait until all pages are purged.'=>'Purger tout : %d pages ajoutées à la file d’attente. Veuillez attendre que toutes les pages soient purgées.','Next.js revalidate'=>'Next.js revalidate','Next.js revalidate settings'=>'Next.js revalidate paramètres','Next.js API'=>'Configuration de l’API Next.js','Allow revalidate all'=>'Autoriser tout revalider','On menu update'=>'Vider les caches lors de la mise à jour d’un menu','Debug'=>'Débogage','NextJS-Revalidate settings tabs'=>'Paramètres de Next.js revalidate','Next.js API config'=>'Configuration de l’API Next.js','Revalidate domain'=>'Domaine','Revalidate path'=>'Chemin de revalidation','Optional. The route that revalidates a single path on the front-end. Leave empty for the default.'=>'Facultatif. L\'itinéraire qui revalide un seul chemin côté client. Laisser vide pour utiliser la valeur par défaut.','FSE revalidate path'=>'Chemin de purge du FSE','Optional. The route that invalidates the front-end’s FSE template snapshot. Leave empty for the default.'=>'Facultatif. Chemin d\'accès qui invalide l\'instantané du modèle FSE du front-end. Laisser vide pour utiliser la valeur par défaut.','Revalidate Secret'=>'Secret de revalidation','Allow revalidate all options'=>'Options de « Tout revalider »','Define which post types offer a revalidate all in the admin bar.'=>'Définir quels types de contenu proposent « Tout revalider » dans la barre d’administration.','All post types'=>'Tous les types','On menu update options'=>'Paramètres de mise à jour de menu','Define which post type will be revalidated when updating a menu.'=>'Définir quel type de post sera vider lors de la mise à jour d’un menu.','Debug options'=>'Paramètres de débogage','Some configuration for easier debug.'=>'Quelques configurations pour faciliter le débogage.','Enable logs'=>'Activer les journaux','Logs will be saved to file located in <code>%s</code>'=>'Les journaux seront sauvegardés dans un fichier stocké dans <code>%s</code>','Next.js revalidate is not configured for this site: the revalidate domain and secret are both required before anything can be revalidated.'=>'Next.js revalidate n\'est pas configurée pour ce site : le domaine et la clé secrète de revalidation sont tous deux obligatoires avant de pouvoir procéder à une revalidation.','its revalidate domain and secret are missing'=>'le domaine et le secret de revalidation sont manquants','its revalidate domain is missing'=>'le domaine de revalidation est manquant','its secret is missing'=>'le secret de revalidation est manquant','Next.js revalidate is not configured for this site — %s. Content is still saved, but every revalidation is refused: the front-end is never asked to rebuild its pages.'=>'Next.js revalidate n\'est pas configurée pour ce site — %s. Le contenu est toujours enregistré, mais chaque revalidation est refusée : le front-end n\'est jamais invité à reconstruire ses pages.','Configure Next.js revalidate'=>'Configurer Next.js revalidate','Admin top bar menuRevalidate'=>'Revalider','Please install composer dependencies for Next.js Revalidate to work'=>'Veuillez installer les dépendances du compositeur pour que Next.js Revalidate fonctionne','Next.js revalidate cannot set up the %s sites of this network in a single request, and it does not set up some of them and leave the rest unable to revalidate. Activate the plugin on each site individually instead.'=>'Next.js revalidate ne peut pas configurer les %s sites de ce réseau en une seule requête, et il ne se contente pas d’en configurer certains en laissant les autres dans l’incapacité de revalider. Activez plutôt le plugin sur chaque site individuellement.','Plugin could not be activated'=>'Impossible d\'activer le plugin']];